import { eq } from "drizzle-orm";

import { db } from "@/db";
import type { Transaction } from "@/db";
import { eventsTable, ticketTypesTable } from "@/db/schema";
import type {
  CreateEventInput,
  CreateTicketTypeInput,
  UpdateEventInput,
  UpdateTicketTypeInput,
} from "@/schemas/event";

// The slug is generated by the service, so it is a parameter rather than part
// of the client-facing input schema.
export async function createEvent(
  hostId: string,
  slug: string,
  input: CreateEventInput,
  tx?: Transaction,
): Promise<{ id: string }> {
  const executor = tx ?? db;
  const [row] = await executor
    .insert(eventsTable)
    .values({ ...input, hostId, slug })
    .returning({ id: eventsTable.id });
  return row;
}

export async function updateEvent(
  eventId: string,
  input: UpdateEventInput,
  tx?: Transaction,
): Promise<void> {
  const executor = tx ?? db;
  await executor.update(eventsTable).set(input).where(eq(eventsTable.id, eventId));
}

export async function deleteEvent(eventId: string, tx?: Transaction): Promise<void> {
  const executor = tx ?? db;
  await executor.delete(eventsTable).where(eq(eventsTable.id, eventId));
}

export async function createTicketType(
  eventId: string,
  input: CreateTicketTypeInput,
  tx?: Transaction,
): Promise<void> {
  const executor = tx ?? db;
  await executor.insert(ticketTypesTable).values({ ...input, eventId });
}

export async function updateTicketType(
  ticketTypeId: string,
  input: UpdateTicketTypeInput,
  tx?: Transaction,
): Promise<void> {
  const executor = tx ?? db;
  await executor.update(ticketTypesTable).set(input).where(eq(ticketTypesTable.id, ticketTypeId));
}

export async function deleteTicketType(ticketTypeId: string, tx?: Transaction): Promise<void> {
  const executor = tx ?? db;
  await executor.delete(ticketTypesTable).where(eq(ticketTypesTable.id, ticketTypeId));
}
